const getEffectiveConfiguration = `-- name: GetEffectiveConfiguration :one
WITH RECURSIVE config_resolution AS (
    -- System default from config_definitions
    SELECT 
        cd.module_name,
        cd.config_key,
        cd.default_value as value,
        'system' as source,
        0 as priority,
        cd.data_type,
        cd.is_overridable
    FROM config_definitions cd
    WHERE cd.module_name = $1 AND cd.config_key = $2
    
    UNION ALL
    
    -- Tenant-level configuration
    SELECT 
        $1::TEXT as module_name,
        $2::TEXT as config_key,
        (tc.settings -> ($1 || '.' || $2)) as value,
        'tenant' as source,
        1 as priority,
        cd.data_type,
        cd.is_overridable
    FROM tenant_configurations tc
    JOIN config_definitions cd ON cd.module_name = $1 AND cd.config_key = $2
    WHERE tc.tenant_id = current_tenant_id()
    AND tc.settings ? ($1 || '.' || $2)
    
    UNION ALL
    
    -- Entity-level configuration
    SELECT 
        $1::TEXT as module_name,
        $2::TEXT as config_key,
        (e.settings -> ($1 || '.' || $2)) as value,
        'entity' as source,
        2 as priority,
        cd.data_type,
        cd.is_overridable
    FROM entities e
    JOIN config_definitions cd ON cd.module_name = $1 AND cd.config_key = $2
    WHERE e.tenant_id = current_tenant_id()
    AND e.uuid = $3
    AND e.deleted_at IS NULL
    AND e.settings ? ($1 || '.' || $2)
)
SELECT 
    module_name,
    config_key,
    value,
    source,
    data_type,
    is_overridable
FROM config_resolution
ORDER BY priority DESC
LIMIT 1
`

