const listTenantEffectiveConfigurations = `-- name: ListTenantEffectiveConfigurations :many
WITH tenant_configs AS (
    SELECT 
        kv.key as config_full_key,
        split_part(kv.key, '.', 1) as module_name,
        split_part(kv.key, '.', 2) as config_key,
        kv.value,
        'tenant' as source
    FROM tenant_configurations tc,
         jsonb_each(tc.settings) as kv(key, value)
    WHERE tc.tenant_id = current_tenant_id()
),
entity_configs AS (
    SELECT 
        kv.key as config_full_key,
        split_part(kv.key, '.', 1) as module_name,
        split_part(kv.key, '.', 2) as config_key,
        kv.value,
        'entity' as source
    FROM entities e,
         jsonb_each(e.settings) as kv(key, value)
    WHERE e.tenant_id = current_tenant_id()
    AND e.uuid = $1
    AND e.deleted_at IS NULL
),
system_configs AS (
    SELECT 
        cd.module_name || '.' || cd.config_key as config_full_key,
        cd.module_name,
        cd.config_key,
        cd.default_value as value,
        'system' as source
    FROM config_definitions cd
    WHERE ($2::TEXT IS NULL OR $2::TEXT = '' OR cd.module_name = $2)
)
SELECT DISTINCT ON (config_full_key)
    config_full_key,
    module_name,
    config_key,
    value,
    source
FROM (
    SELECT config_full_key, module_name, config_key, value, source, 2 as priority FROM entity_configs
    UNION ALL
    SELECT config_full_key, module_name, config_key, value, source, 1 as priority FROM tenant_configs
    UNION ALL
    SELECT config_full_key, module_name, config_key, value, source, 0 as priority FROM system_configs
) combined
ORDER BY config_full_key, priority DESC
`

type ListTenantEffectiveConfigurationsParams struct {
	EntityID     uuid.UUID `json:"entity_id"`
	ModuleFilter *string   `json:"module_filter"`
}

type ListTenantEffectiveConfigurationsRow struct {
	ConfigFullKey any    `json:"config_full_key"`
	ModuleName    string `json:"module_name"`
	ConfigKey     string `json:"config_key"`
	Value         any    `json:"value"`
	Source        string `json:"source"`
}

func (q *Queries) ListTenantEffectiveConfigurations(ctx context.Context, arg ListTenantEffectiveConfigurationsParams) ([]*ListTenantEffectiveConfigurationsRow, error) {
	rows, err := q.db.Query(ctx, listTenantEffectiveConfigurations, arg.EntityID, arg.ModuleFilter)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []*ListTenantEffectiveConfigurationsRow{}
	for rows.Next() {
		var i ListTenantEffectiveConfigurationsRow
		if err := rows.Scan(
			&i.ConfigFullKey,
			&i.ModuleName,
			&i.ConfigKey,
			&i.Value,
			&i.Source,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchConfigurations = `-- name: SearchConfigurations :many

WITH all_configs AS (
    -- System configurations
    SELECT 
        cd.module_name,
        cd.config_key,
        cd.module_name || '.' || cd.config_key as full_key,
        cd.default_value as value,
        'system' as source,
        NULL::UUID as tenant_id,
        NULL::UUID as entity_id,
        cd.data_type,
        cd.updated_at
    FROM config_definitions cd
    
    UNION ALL
    
    -- Tenant configurations
    SELECT 
        split_part(key, '.', 1) as module_name,
        split_part(key, '.', 2) as config_key,
        key as full_key,
        value,
        'tenant' as source,
        tc.tenant_id,
        NULL::UUID as entity_id,
        cd.data_type,
        tc.updated_at
    FROM tenant_configurations tc,
         jsonb_each(tc.settings) as setting(key, value)
    JOIN config_definitions cd ON cd.module_name = split_part(key, '.', 1) 
                              AND cd.config_key = split_part(key, '.', 2)
    WHERE tc.tenant_id = current_tenant_id()
    
    UNION ALL
    
    -- Entity configurations
    SELECT 
        split_part(key, '.', 1) as module_name,
        split_part(key, '.', 2) as config_key,
        key as full_key,
        value,
        'entity' as source,
        e.tenant_id,
        e.uuid as entity_id,
        cd.data_type,
        e.updated_at
    FROM entities e,
         jsonb_each(e.settings) as setting(key, value)
    JOIN config_definitions cd ON cd.module_name = split_part(key, '.', 1) 
                              AND cd.config_key = split_part(key, '.', 2)
    WHERE e.tenant_id = current_tenant_id()
    AND e.deleted_at IS NULL
    AND ($8::UUID IS NULL OR e.uuid = $8)
)
SELECT module_name, config_key, full_key, value, source, tenant_id, entity_id, data_type, updated_at
FROM all_configs
WHERE ($1::TEXT[] IS NULL OR module_name = ANY($1::TEXT[]))
AND ($2::TEXT IS NULL OR $2::TEXT = '' OR full_key ILIKE '%' || $2 || '%')
AND ($3::TEXT[] IS NULL OR source = ANY($3::TEXT[]))
AND ($4::TIMESTAMPTZ IS NULL OR updated_at >= $4)
ORDER BY 
    CASE WHEN $5 = 'module' THEN module_name END,
    CASE WHEN $5 = 'updated_at' THEN updated_at END DESC,
    full_key
LIMIT $7 OFFSET $6
`

type SearchConfigurationsParams struct {
	ModulesFilter  []string     `json:"modules_filter"`
	SearchTerm     *string      `json:"search_term"`
	SourcesFilter  []string     `json:"sources_filter"`
	UpdatedAfter   sql.NullTime `json:"updated_after"`
	SortBy         any          `json:"sort_by"`
	OffsetCount    int32        `json:"offset_count"`
	LimitCount     int32        `json:"limit_count"`
	EntityIDFilter *uuid.UUID   `json:"entity_id_filter"`
}

type SearchConfigurationsRow struct {
	ModuleName string     `json:"module_name"`
	ConfigKey  string     `json:"config_key"`
	FullKey    any        `json:"full_key"`
	Value      []byte     `json:"value"`
	Source     string     `json:"source"`
	TenantID   *uuid.UUID `json:"tenant_id"`
	EntityID   *uuid.UUID `json:"entity_id"`
	DataType   string     `json:"data_type"`
	UpdatedAt  time.Time  `json:"updated_at"`
}

// ==========================================
// Configuration Search Queries
// ==========================================
func (q *Queries) SearchConfigurations(ctx context.Context, arg SearchConfigurationsParams) ([]*SearchConfigurationsRow, error) {
	rows, err := q.db.Query(ctx, searchConfigurations,
		arg.ModulesFilter,
		arg.SearchTerm,
		arg.SourcesFilter,
		arg.UpdatedAfter,
		arg.SortBy,
		arg.OffsetCount,
		arg.LimitCount,
		arg.EntityIDFilter,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []*SearchConfigurationsRow{}
	for rows.Next() {
		var i SearchConfigurationsRow
		if err := rows.Scan(
			&i.ModuleName,
			&i.ConfigKey,
			&i.FullKey,
			&i.Value,
			&i.Source,
			&i.TenantID,
			&i.EntityID,
			&i.DataType,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

